import React, { useState, useEffect } from 'react';
import './App.css';
import { 
  handleAddCategory, 
  handleDeleteCategory,
  handleAddCriteria,
  handleEditCriteria,
  handleDeleteCriteria,
  handleAddJudge,
  handleDeleteJudge,
  handleAddContestant,
  handleDeleteContestant,
  handleEliminateContestant,
  handleDisqualifyContestant,
  refreshAllData,
  refreshCriteria
} from './dataManagement';
import Dashboard from './components/Dashboard';
import PublicPage from './PublicPage';
import Category from './Category';
import Criteria from './Criteria';

function App() {
  // Authentication state
  const [isAdmin, setIsAdmin] = useState(false);
  const [authPin, setAuthPin] = useState('');
  const [judgePin, setJudgePin] = useState('');
  const [showJudgePin, setShowJudgePin] = useState(false);
  const [showAdminPin, setShowAdminPin] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showAuth, setShowAuth] = useState(false);
  const [showPublicPage, setShowPublicPage] = useState(true);
  const [showJudgeLogin, setShowJudgeLogin] = useState(false);
  const [currentJudge, setCurrentJudge] = useState(null);
  const [showInfoModal, setShowInfoModal] = useState(false);
  const [language, setLanguage] = useState('en'); // 'en' or 'tl'

  // Scoring state
  const [showScoringModal, setShowScoringModal] = useState(false);
  const [selectedContestant, setSelectedContestant] = useState(null);
  const [scoringCriteria, setScoringCriteria] = useState([]);
  const [scores, setScores] = useState({});
  const [submittedScores, setSubmittedScores] = useState([]);
  const [scoringData, setScoringData] = useState({});
  const [scoringLoading, setScoringLoading] = useState(false);
  const [scoringError, setScoringError] = useState('');
  const [recentActivities, setRecentActivities] = useState([]);

  // Data state - loaded from backend
  const [categories, setCategories] = useState([]);
  const [categoryInput, setCategoryInput] = useState('');

  const [criteria, setCriteria] = useState([]);
  const [criteriaInput, setCriteriaInput] = useState({
    name: '',
    percentage: '',
    min: '',
    max: ''
  });
  const [selectedCategory, setSelectedCategory] = useState('Talent');

  const [judges, setJudges] = useState([]);
  const [judgeInput, setJudgeInput] = useState('');

  const [contestants, setContestants] = useState([]);
  const [contestantInput, setContestantInput] = useState('');

  // Navigation state
  const [activeSection, setActiveSection] = useState('dashboard');

  // Notification state
  const [notification, setNotification] = useState(null);
  const [showContestantSelection, setShowContestantSelection] = useState(false);

  // Show notification function
  const showNotification = (message, type = 'info') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  // Load recent activities
  const loadRecentActivities = async () => {
    try {
      // Get scores submitted by current judge
      const scoresResponse = await fetch(`http://localhost/Tabolator_Casestudy/backend/api/scores?judge_id=${currentJudge?.id}`);
      const scoresData = await scoresResponse.json();

      // Get all contestants for activity context
      const contestantsResponse = await fetch('http://localhost/Tabolator_Casestudy/backend/api/contestants');
      const contestantsData = await contestantsResponse.json();

      const activities = [];

      // Process scores into activities
      if (scoresData.success && scoresData.data) {
        scoresData.data.forEach(score => {
          const contestant = contestantsData.data?.find(c => c.id === score.contestant_id);
          if (contestant) {
            activities.push({
              id: score.id,
              type: 'score_submitted',
              message: `Score submitted for ${contestant.name}`,
              details: `Total Score: ${score.total_score || 'N/A'}%`,
              timestamp: score.created_at || score.timestamp,
              icon: 'fi-rr-check',
              color: 'success'
            });
          }
        });
      }

      // Add contestant status changes
      if (contestantsData.success && contestantsData.data) {
        contestantsData.data.forEach(contestant => {
          if (contestant.status === 'Eliminated' && contestant.updated_at) {
            activities.push({
              id: `elim_${contestant.id}`,
              type: 'eliminated',
              message: `${contestant.name} eliminated`,
              details: 'Status changed to Eliminated',
              timestamp: contestant.updated_at,
              icon: 'fi-rr-exclamation',
              color: 'warning'
            });
          } else if (contestant.status === 'Disqualified' && contestant.updated_at) {
            activities.push({
              id: `disq_${contestant.id}`,
              type: 'disqualified',
              message: `${contestant.name} disqualified`,
              details: 'Status changed to Disqualified',
              timestamp: contestant.updated_at,
              icon: 'fi-rr-cross-circle',
              color: 'error'
            });
          }
        });
      }

      // Sort by timestamp (most recent first) and take latest 5
      const sortedActivities = activities
        .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
        .slice(0, 5);

      setRecentActivities(sortedActivities);
    } catch (error) {
      console.error('Failed to load recent activities:', error);
      // Set empty array on error
      setRecentActivities([]);
    }
  };

  // Load initial data from backend
  useEffect(() => {
    const loadInitialData = async () => {
      try {
        // Fetch all data from backend
        const [contestantsResponse, judgesResponse, categoriesResponse, criteriaResponse] = await Promise.all([
          fetch('http://localhost/Tabolator_Casestudy/backend/api/contestants'),
          fetch('http://localhost/Tabolator_Casestudy/backend/api/judges'),
          fetch('http://localhost/Tabolator_Casestudy/backend/api/categories'),
          fetch('http://localhost/Tabolator_Casestudy/backend/api/criteria')
        ]);

        const contestantsData = await contestantsResponse.json();
        const judgesData = await judgesResponse.json();
        const categoriesData = await categoriesResponse.json();
        const criteriaData = await criteriaResponse.json();

        // Set state with real data
        setCategories(categoriesData.data || []);
        setJudges(judgesData.data || []);
        setContestants(contestantsData.data || []);
        setCriteria(criteriaData.data || []);

      } catch (error) {
        console.error('Failed to load initial data:', error);
      }
    };

    loadInitialData();
  }, []);

  // Load recent activities when judge logs in
  useEffect(() => {
    if (currentJudge) {
      loadRecentActivities();
    }
  }, [currentJudge]);

  // Refresh activities when scores are submitted
  useEffect(() => {
    if (currentJudge && submittedScores.length > 0) {
      loadRecentActivities();
    }
  }, [submittedScores]);

  // Format timestamp to relative time
  const formatRelativeTime = (timestamp) => {
    const now = new Date();
    const time = new Date(timestamp);
    const diffMs = now - time;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins} minute${diffMins > 1 ? 's' : ''} ago`;
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
    return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;
  };

  // ================================
  // AUTHENTICATION FUNCTIONS
  // ================================

  // Admin authentication
  const handleAdminAuth = () => {
    // Simple PIN authentication (in production, this should be secure)
    const adminPin = '1234'; // Change this in production
    if (authPin === adminPin) {
      setIsAdmin(true);
      setShowAuth(false);
    } else {
      alert('Invalid PIN. Please try again.');
    }
  };

  // Judge authentication
  const handleJudgeLogin = async (e) => {
    e.preventDefault();

    if (!judgePin.trim()) {
      setError(language === 'tl' ? 'Mangyaring kang PIN' : 'Please enter your PIN');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Call appropriate login API based on login type
      const response = await fetch('http://localhost/Tabolator_Casestudy/backend/api/judge-login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ pin: judgePin }),
      });

      const data = await response.json();

      if (data.success) {
        // Login successful - call to appropriate handler
        setCurrentJudge(data.judge);
        setShowJudgeLogin(false);
        setShowAuth(false);
        setJudgePin('');
      } else {
        setError(language === 'tl' ? 'Maling PIN' : data.message || 'Invalid PIN');
      }
    } catch (err) {
      setError(language === 'tl' ? 'Network error. Subukan muli.' : 'Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // ================================
  // UI HELPER FUNCTIONS
  // ================================

  const handleLogout = () => {
    setIsAdmin(false);
    setShowAuth(true);
    setShowPublicPage(false);
    setCurrentJudge(null);
    setAuthPin('');
    setJudgePin('');
    setShowJudgeLogin(false);
  };

  const handleInfoModal = () => {
    setShowInfoModal(true);
  };

  const handleCloseModal = () => {
    setShowInfoModal(false);
  };

  // ================================
  // SCORING FUNCTIONS
  // ================================

  // Scoring functions
  const handleStartScoring = (contestant) => {
    setSelectedContestant(contestant);

    // Debug: Log criteria data
    console.log('Criteria data:', criteria);

    // Check if there are any criteria
    if (!criteria || criteria.length === 0) {
      showNotification('No scoring criteria available. Please add criteria in the admin panel first.', 'warning');
      return;
    }

    // Load scoring criteria with fallback values
    const criteriaList = criteria.map(c => ({
      id: c.id,
      name: c.name,
      percentage: parseFloat(c.percentage) || 0,
      min: parseFloat(c.min) || 0,
      max: parseFloat(c.max) || 100,
      score: ''
    }));

    console.log('Processed criteria list:', criteriaList);
    setScoringCriteria(criteriaList);

    // Initialize scores object
    const initialScores = {};
    criteriaList.forEach(c => {
      initialScores[c.id] = '';
    });
    setScores(initialScores);

    setShowScoringModal(true);
  };

  const handleScoreChange = (criteriaId, value) => {
    // Validate score is within range
    const criteriaItem = scoringCriteria.find(c => c.id === criteriaId);
    if (criteriaItem) {
      // Allow empty value or valid number within range
      if (value === '') {
        setScores(prev => ({
          ...prev,
          [criteriaId]: ''
        }));
        return;
      }

      const numValue = parseFloat(value);
      if (!isNaN(numValue) && numValue >= criteriaItem.min && numValue <= criteriaItem.max) {
        setScores(prev => ({
          ...prev,
          [criteriaId]: value
        }));
      }
    }
  };

  const calculateTotalScore = () => {
    let total = 0;
    scoringCriteria.forEach(criteria => {
      const score = parseFloat(scores[criteria.id]) || 0;
      const weightedScore = (score / criteria.max) * criteria.percentage;
      total += weightedScore;
    });
    return total.toFixed(2);
  };

  const handleSubmitScores = async () => {
    // Validate all scores are filled
    const allScoresFilled = scoringCriteria.every(c => scores[c.id] !== '');

    if (!allScoresFilled) {
      showNotification('Please fill in all scores before submitting', 'error');
      return;
    }

    const totalScore = calculateTotalScore();

    const scoreData = {
      judgeId: currentJudge.id,
      contestantId: selectedContestant.id,
      scores: scores,
      totalScore: totalScore,
      timestamp: new Date().toISOString()
    };

    try {
      // Send to backend
      const response = await fetch('http://localhost/Tabolator_Casestudy/backend/api/scores', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(scoreData)
      });

      if (response.ok) {
        showNotification(`Scores submitted successfully! Total Score: ${totalScore}`, 'success');
